const params=new URLSearchParams(location.search),requested=params.get('species')||'mango',language=localStorage.getItem('tfruitllm-language')==='zh'?'zh':'en';
const root=document.querySelector('#genomeContent'),back=document.querySelector('#resourceBack');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const text={en:{back:'Research resources',catalog:'PUBLIC GENOME ASSEMBLIES',assemblies:'assemblies',updated:'NCBI data updated',modelTitle:'Genome version used by TropicalfruitLLM v1.0',modelBody:'No single fixed genome assembly. The model was fine-tuned from literature, question-answer and multi-omics evidence; its weights are not built from or bound to one unified genome FASTA. For reproducible analysis, cite the exact assembly accession used.',public:'NCBI public assembly',accession:'Accession',name:'Assembly name',sample:'Cultivar / isolate',level:'Assembly level',date:'Release date',project:'BioProject',record:'NCBI record',download:'Download genome',empty:'No public assembly is currently listed for this species.'},zh:{back:'返回研究资源',catalog:'公开基因组组装目录',assemblies:'个组装版本',updated:'NCBI 数据更新于',modelTitle:'TropicalfruitLLM v1.0 使用的基因组版本',modelBody:'未绑定单一固定基因组版本。模型基于文献、问答与多组学证据微调，模型权重并非由某一个统一的基因组 FASTA 组装构建。涉及可复现分析时，应明确引用实际使用的组装登录号。',public:'NCBI 公开组装',accession:'登录号',name:'组装名称',sample:'品种 / 样本',level:'组装层级',date:'发布日期',project:'BioProject',record:'NCBI 记录',download:'下载基因组',empty:'NCBI 当前未列出该物种的公开组装。'}}[language];
document.documentElement.lang=language==='zh'?'zh-CN':'en';back.textContent=text.back;
const sampleLabel=assembly=>[assembly.cultivar,assembly.isolate&&`isolate=${assembly.isolate}`].filter(Boolean).join(' · ')||'—';
fetch('data/genomes.json').then(response=>response.json()).then(data=>{
  const species=data.species.find(item=>item.key===requested)||data.species[0],assemblies=species.assemblies||[];
  document.title=`${species.commonName} Genome Assemblies | TropicalfruitLLM v1.0`;
  root.innerHTML=`<section class="genome-heading"><p class="eyebrow">${text.catalog}</p><h1>${esc(species.commonName)}</h1><p class="scientific-name">${esc(species.scientificName)}</p><div class="genome-summary"><strong>${assemblies.length}</strong><span>${text.assemblies}</span><small>${text.updated} ${esc(data.updated)}</small></div></section><section class="model-genome-note"><span>MODEL GENOME STATUS</span><div><h2>${text.modelTitle}</h2><p>${text.modelBody}</p></div></section><section class="assembly-section"><div class="assembly-list">${assemblies.length?assemblies.map(assembly=>`<article class="assembly-card"><header><span>${text.public}</span><strong>${esc(assembly.accession)}</strong></header><dl><div><dt>${text.name}</dt><dd>${esc(assembly.assemblyName||'—')}</dd></div><div><dt>${text.sample}</dt><dd>${esc(sampleLabel(assembly))}</dd></div><div><dt>${text.level}</dt><dd>${esc(assembly.level||'—')}</dd></div><div><dt>${text.date}</dt><dd>${esc(assembly.releaseDate||'—')}</dd></div><div><dt>${text.project}</dt><dd>${esc(assembly.bioproject||'—')}</dd></div></dl><footer><a href="${esc(assembly.ncbiUrl)}" target="_blank" rel="noopener noreferrer">${text.record}</a><a class="primary" href="${esc(assembly.downloadUrl||assembly.ncbiUrl)}" target="_blank" rel="noopener noreferrer">${text.download}</a></footer></article>`).join(''):`<p class="empty-assemblies">${text.empty}</p>`}</div></section>`;
}).catch(()=>{root.innerHTML='<p class="loading">Genome assembly data are temporarily unavailable.</p>'});
